import React, { useEffect } from "react";
import { initTagCloud } from "../../utils/tagCloud";

const Skills = () => {
  useEffect(() => {
    // Wait for jQuery and svg3DTagCloud to load
    const checkAndInit = () => {
      if (window.$ && window.$.fn.svg3DTagCloud) {
        initTagCloud();
      } else {
        // Retry after a short delay if scripts aren't loaded yet
        setTimeout(checkAndInit, 100);
      }
    };

    // Start checking after a short delay to allow scripts to load
    const timer = setTimeout(checkAndInit, 500);

    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="row skills mb-50">
      <div className="col-md-12 skill-container" style={{ display: 'flex', justifyContent: 'center' }}>
        <div id="holder"></div>
      </div>
    </div>
  );
};

export default Skills;
