import React from "react";
import AWSLogo from "../../assets/img/certifications_and_courses/aws.png";
import AWSCertification from "../../assets/img/certifications_and_courses/aws_certification.png";

const certificationsContent = [
  {
    year: "Feb 2026 - Feb 2029",
    title: "AWS Certified Cloud Practitioner",
    provider: "Amazon Web Services",
    logo: AWSLogo,
    credentialId: "2aea1ac3c7c04bb294cd1bd40f16e5ed",
    credentialUrl: "https://www.credly.com/badges/e6fb75ea-30ca-4111-b2b6-6129c5fdba20",
    images: [AWSCertification],
  },
];

const Certifications = () => {
  const openImageInNewTab = (src) => {
    window.open(src, '_blank');
  };

  return (
    <>
      <ul>
        {certificationsContent.map((val, i) => (
          <li key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: '10px', marginLeft: '-10px' }}>
            <div className="icon icon-logo" style={{ flexShrink: 0, width: '50px', height: '50px', marginTop: '-5px' }}>
              <img src={val.logo} alt={`${val.provider} logo`} style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
            </div>
            <div style={{ flex: 1 }}>
              <h6 className="poppins-font text-uppercase" style={{ marginBottom: '5px' }}>
                {val.title}
                <span className="place open-sans-font">{val.provider}</span>
              </h6>
              <span className="time open-sans-font text-uppercase" style={{ display: 'block', marginBottom: '10px', fontSize: '12px' }}>{val.year}</span>
              {val.credentialId && (
                <p className="open-sans-font" style={{ marginBottom: '5px' }}>
                  <strong>Credential ID:</strong> {val.credentialId}
                </p>
              )}
              {val.credentialUrl && (
                <p className="open-sans-font" style={{ marginBottom: '10px' }}>
                  <strong>Credential URL:</strong>{' '}
                  <a
                    href={val.credentialUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                    style={{ color: '#007bff', textDecoration: 'none' }}
                    onMouseOver={(e) => e.currentTarget.style.textDecoration = 'underline'}
                    onMouseOut={(e) => e.currentTarget.style.textDecoration = 'none'}
                  >
                    View Certificate
                  </a>
                </p>
              )}
              {val.images && val.images.length > 0 && (
                <div className="certification-images mt-3">
                  {val.images.map((img, idx) => (
                    <img
                      key={idx}
                      src={img}
                      alt={`${val.title} certificate ${idx + 1}`}
                      onClick={() => openImageInNewTab(img)}
                      style={{
                        maxWidth: '125px',
                        height: 'auto',
                        marginTop: '0px',
                        marginBottom: '20px',
                        marginRight: '10px',
                        border: '1px solid #ddd',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        transition: 'transform 0.2s, box-shadow 0.2s'
                      }}
                      onMouseOver={(e) => {
                        e.currentTarget.style.transform = 'scale(1.05)';
                        e.currentTarget.style.boxShadow = '0 4px 8px rgba(0, 0, 0, 0.2)';
                      }}
                      onMouseOut={(e) => {
                        e.currentTarget.style.transform = 'scale(1)';
                        e.currentTarget.style.boxShadow = 'none';
                      }}
                    />
                  ))}
                </div>
              )}
            </div>
          </li>
        ))}
      </ul>
    </>
  );
};

export default Certifications;
